.LC2:
	.string	"help"
.LC3:
	.string	"Display this summary"
.LC4:
	.string	"config"
	.align 8
.LC5:
	.string	"Configuration file to use. \"\" = none. Default from env variable OPENSSL_CONF"
.LC6:
	.string	"section"
	.align 8
.LC7:
	.string	"Section(s) in config file to get options from. \"\" = 'default'. Default 'cmp'"
.LC8:
	.string	"verbosity"
	.align 8
.LC9:
	.string	"Log level; 3=ERR, 4=WARN, 6=INFO, 7=DEBUG, 8=TRACE. Default 6 = INFO"
.LC10:
	.string	"Generic message options:\n"
.LC11:
	.string	"cmd"
	.align 8
.LC12:
	.string	"CMP request to send: ir/cr/kur/p10cr/rr/genm"
.LC13:
	.string	"infotype"
	.align 8
.LC14:
	.string	"InfoType name for requesting specific info in genm, with specific support"
	.align 8
.LC15:
	.string	"for 'caCerts' and 'rootCaCert'"
.LC16:
	.string	"profile"
	.align 8
.LC17:
	.string	"Certificate profile name to place in generalInfo field of request PKIHeader"
.LC18:
	.string	"geninfo"
	.align 8
.LC19:
	.string	"Comma-separated list of OID and value to place in generalInfo PKIHeader"
	.align 8
.LC20:
	.string	"of form <OID>:int:<n> or <OID>:str:<s>, e.g. '1.2.3.4:int:56789, id-kp:str:name'"
	.align 8
.LC21:
	.string	"Certificate enrollment options:\n"
.LC22:
	.string	"newkey"
	.align 8
.LC23:
	.string	"Private or public key for the requested cert. Default: CSR key or client key"
.LC24:
	.string	"newkeypass"
	.align 8
.LC25:
	.string	"New private key pass phrase source"
.LC26:
	.string	"subject"
	.align 8
.LC27:
	.string	"Distinguished Name (DN) of subject to use in the requested cert template"
	.align 8
.LC28:
	.string	"For kur, default is subject of -csr arg or reference cert (see -oldcert)"
	.align 8
.LC29:
	.string	"this default is used for ir and cr only if no Subject Alt Names are set"
.LC30:
	.string	"days"
	.align 8
.LC31:
	.string	"Requested validity time of the new certificate in number of days"
.LC32:
	.string	"reqexts"
	.align 8
.LC33:
	.string	"Name of config file section defining certificate request extensions."
	.align 8
.LC34:
	.string	"Augments or replaces any extensions contained CSR given with -csr"
.LC35:
	.string	"sans"
	.align 8
.LC36:
	.string	"Subject Alt Names (IPADDR/DNS/URI) to add as (critical) cert req extension"
.LC37:
	.string	"san_nodefault"
	.align 8
.LC38:
	.string	"Do not take default SANs from reference certificate (see -oldcert)"
.LC39:
	.string	"policies"
	.align 8
.LC40:
	.string	"Name of config file section defining policies certificate request extension"
.LC41:
	.string	"policy_oids"
	.align 8
.LC42:
	.string	"Policy OID(s) to add as policies certificate request extension"
.LC43:
	.string	"policy_oids_critical"
	.align 8
.LC44:
	.string	"Flag the policy OID(s) given with -policy_oids as critical"
.LC45:
	.string	"popo"
	.align 8
.LC46:
	.string	"Proof-of-Possession (POPO) method to use for ir/cr/kur where"
